        raise AssertionError(f"rotate must change the list it is given, but nums is still {nums!r}: it looks like you returned a new list instead")
    return nums
def every_k_up_to_three_turns(max_length):
    # Compares rotate with the slowest, simplest rotation (one step at a time) for every small length and every k up to three full turns.
    for length in range(max_length + 1):
        for k in range(3 * length + 2):
            expected = list(range(length))
            for _ in range(k):
                if expected:
                    expected.insert(0, expected.pop())
            got = rotated(range(length), k)
            if got != expected:
                raise AssertionError(f"rotate(nums, {k}) on {list(range(length))} left {got!r}, expected {expected!r}")
    return True

solution:
def rotate(nums, k):
    if not nums:
        return
    k %= len(nums)                       # a full turn changes nothing, so only the remainder matters
    if k:
        nums[:] = nums[-k:] + nums[:-k]  # nums[:] writes into the caller's list; nums = ... would only rebind the name
